export const fixture = Object.freeze({income:85000,balance:42800,buffer:7000,goalSaved:18000,goalTarget:30000,emergency:96000,emergencyTarget:150000,contribution:8000});
export const commitments = Object.freeze([{name:'Rent',amount:18000,date:'05'},{name:'Electricity + utilities',amount:2400,date:'08'},{name:'Internet + mobile',amount:1200,date:'10'},{name:'Subscriptions',amount:1100,date:'11'},{name:'SIP',amount:4000,date:'12'}]);
export const money = n => (n<0?'−':'')+'₹'+new Intl.NumberFormat('en-IN').format(Math.abs(n));
export function parseCurrency(value){const cleaned=String(value).trim().replace(/^₹\s*/,'').replaceAll(',','');return /^\d+$/.test(cleaned)?Number(cleaned):NaN;}
export const total = commitments.reduce((sum,c)=>sum+c.amount,0);
export function analyze(amount,contribution=fixture.contribution){const after=fixture.balance-total-amount;const gap=Math.max(0,fixture.buffer-after);return {amount,available:fixture.balance-amount,before:fixture.balance-total,after,gap,proposed:Math.max(0,contribution-gap),released:Math.min(gap,contribution),covered:after>=0};}
export function estimatedDate(contribution){return contribution===8000?'Nov 08':contribution===5100?'Nov 20':contribution===10000?'Oct 30':contribution<8000?'Later than Nov 08':'Earlier than Nov 08';}
export function transition(plan,event){if(event==='APPLY')return {...plan,state:'ADJUSTMENT_APPLIED',contribution:plan.proposed,date:estimatedDate(plan.proposed),previous:{contribution:plan.contribution,date:plan.date}};if(event==='UNDO'&&plan.previous)return {...plan,...plan.previous,state:'ADJUSTMENT_UNDONE',previous:null};return {...plan,state:event};}
